const upsertSyncPending = `-- name: UpsertSyncPending :one
INSERT INTO sync_connections (user_id, service, status, pending_secret, pending_user_code, pending_url,
                              pending_expires_at, pending_interval, pending_polled_at)
VALUES (?1, ?2, 'pending', ?3, ?4,
        ?5, ?6, ?7, NULL)
ON CONFLICT (user_id, service) DO UPDATE SET
    pending_secret = excluded.pending_secret, pending_user_code = excluded.pending_user_code,
    pending_url = excluded.pending_url, pending_expires_at = excluded.pending_expires_at,
    pending_interval = excluded.pending_interval, pending_polled_at = NULL, updated_at = unixepoch()
RETURNING id, user_id, service, status, secret, token_expires_at, account, remote_id, features, cursors, pending_secret, pending_user_code, pending_url, pending_expires_at, pending_interval, pending_polled_at, connected_at, last_sync_at, last_error, last_error_at, created_at, updated_at
`

type UpsertSyncPendingParams struct {
	UserID           int64         `json:"userId"`
	Service          string        `json:"service"`
	PendingSecret    []byte        `json:"pendingSecret"`
	PendingUserCode  string        `json:"pendingUserCode"`
	PendingUrl       string        `json:"pendingUrl"`
	PendingExpiresAt sql.NullInt64 `json:"pendingExpiresAt"`
	PendingInterval  int64         `json:"pendingInterval"`
}

// Starts (or restarts) a pairing; an existing link keeps working meanwhile.
func (q *Queries) UpsertSyncPending(ctx context.Context, arg UpsertSyncPendingParams) (SyncConnection, error) {
	row := q.db.QueryRowContext(ctx, upsertSyncPending,
		arg.UserID,
		arg.Service,
		arg.PendingSecret,
		arg.PendingUserCode,
		arg.PendingUrl,
		arg.PendingExpiresAt,
		arg.PendingInterval,
	)
	var i SyncConnection
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Service,
		&i.Status,
		&i.Secret,
		&i.TokenExpiresAt,
		&i.Account,
		&i.RemoteID,
		&i.Features,
		&i.Cursors,
		&i.PendingSecret,
		&i.PendingUserCode,
		&i.PendingUrl,
		&i.PendingExpiresAt,
		&i.PendingInterval,
		&i.PendingPolledAt,
		&i.ConnectedAt,
		&i.LastSyncAt,
		&i.LastError,
		&i.LastErrorAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

